def solve(xs: list[int]) -> int:
    total = 0
    for x in xs:
        n = abs(x)
        while n >= 10:
            s = 0
            while n > 0:
                s += n % 10
                n //= 10
            n = s
        total += n
    return total

def solve(xs: list[int]) -> int:
    if len(xs) < 3:
        return 0
    best = 0
    for i in range(len(xs) - 2):
        w = xs[i:i + 3]
        best = max(best, max(w) - min(w))
    return best
